<script setup>
import SubjectFields from "@/components/SubjectFields.vue";
import KnowledgePicker from "@/components/KnowledgePicker.vue";
import QuestionEditor from "@/components/QuestionEditor.vue";
import {ref,computed,onMounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import draggable from 'vuedraggable';
import {Plus,Save,Eye,Upload,ArrowUp,ArrowDown,Trash2,GripVertical,BookOpen,RefreshCw} from '@/components/app/icons.js';
import {curriculumApi as api} from '@/services/curriculum.js';
import {modelApi} from '@/services/models.js';
import {createId} from '@/services/platform.js';
import Workspace from './Workspace.vue';
import LessonPreview from './LessonPreview.vue';
const route=useRoute(),router=useRouter();
const catalog=ref([]),points=ref([]),caseOptions=ref([]),courseId=ref(''),selected=ref(null),draft=ref(null),tab=ref('content'),busy=ref(false),loading=ref(true),dirty=ref(false),error=ref(''),notice=ref(''),modal=ref(''),createTitle=ref(''),createUnitId=ref(''),preview=ref(false),historyContent=ref(null);
const search=ref(''),settingsOpen=ref(false),newGrade=ref(''),newSubject=ref('');
const blockNames={explanation:'讲解',example:'例题',activity:'互动',discussion:'讨论',practice:'练习',check:'独立检查'};
const filteredUnits=computed(()=>{const query=search.value.trim().toLowerCase();return (course.value?.units||[]).map(u=>({...u,lessons:u.lessons.filter(l=>!query||(l.draft?.title||l.title).toLowerCase().includes(query)||u.title.toLowerCase().includes(query))})).filter(u=>!query||u.lessons.length)});
const course=computed(()=>catalog.value.find(c=>c.id===courseId.value));
const allLessons=computed(()=>catalog.value.flatMap(c=>c.units.flatMap(u=>u.lessons)));
const kinds=[{value:'explanation',label:'讲解'},{value:'example',label:'例题'},{value:'activity',label:'天平互动（数学）'},{value:'discussion',label:'讨论与探究'},{value:'practice',label:'随堂练习'},{value:'check',label:'独立检查'}];
const questionKinds=[{value:'practice',label:'随堂练习'},{value:'check',label:'独立检查'},{value:'replacement',label:'替换新题'}];
function changed(){dirty.value=true;if(selected.value)selected.value.reviewed=false}
async function lists(){catalog.value=await api.catalog();points.value=await api.knowledge();if(!courseId.value)courseId.value=catalog.value[0]?.id||''}
function apply(item){selected.value=item;draft.value=structuredClone(item.draft||item.published||item.lastPublished);dirty.value=false}
async function chooseCourse(id){if(id===courseId.value)return;if(dirty.value&&!confirm('切换课程将放弃未保存课时修改，继续？'))return;dirty.value=false;search.value='';courseId.value=id;const candidate=allLessons.value.find(l=>l.courseId===id);if(candidate)await select(candidate.id);else{selected.value=null;draft.value=null;tab.value='content';await router.replace({query:{course:id}})}}
async function select(id){if(dirty.value&&!confirm('当前课时有未保存修改，是否放弃后切换？'))return;error.value='';loading.value=true;try{const item=await api.lesson(id);apply(item);tab.value='content';courseId.value=item.courseId;await router.replace({query:{course:item.courseId,lesson:id}})}catch(e){error.value=e.message}finally{loading.value=false}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){const result=await api.saveLesson(selected.value.id,{data:draft.value});apply(result);await lists();notice.value='课时草稿已保存'}
async function action(name){await run(async()=>{if(name==='publish'&&!confirm('发布后教师可选用，学生可阅读；已发布任务仍保留原版本。确认发布？'))return;if(name==='withdraw'&&!confirm('停用后不能发布新任务，已有任务和学习记录保留。确认停用？'))return;if(dirty.value)await save();const result=await api.action(selected.value.id,name);apply(result);await lists();notice.value={review:'内容与所列题目已核对',verify:'所列方程与参考答案通过程序核对',publish:'课时已发布',withdraw:'课时已停用',revise:'已创建修订草稿'}[name]})}
async function uploadBlock(block,event){const file=event.target.files?.[0];if(!file)return;await run(async()=>{const asset=await modelApi.upload(file);block.imageUrl=asset.url;block.imageAlt=file.name;changed()})}
function addBlock(){draft.value.blocks.push({id:createId('block'),type:'explanation',title:'新内容块',content:'',required:true,questionIds:[]});changed()}
function changeKind(block,value){block.type=value;if(value==='activity')block.activity={type:'balance',base:5,step:1,max:10};changed()}
function move(list,index,delta){const target=index+delta;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];changed()}
function remove(list,index,label){if(confirm('删除'+label+'后需重新核对发布，已有任务不受影响。继续？')){list.splice(index,1);changed()}}
function addQuestion(){draft.value.questions.push({id:createId('question'),kind:'practice',type:'expression',responseType:'short_answer',gradingMode:'manual',prompt:'',equation:'',answer:'',hint:'',explanation:'',feedback:[],knowledgeIds:[]});changed()}
async function create(){await run(async()=>{if(dirty.value&&selected.value?.draft)await save();if(!createTitle.value.trim())throw new Error('请填写名称。');let id;if(modal.value==='course'){if(!newGrade.value.trim()||!newSubject.value.trim())throw new Error('请选择年级与学科。');id=(await api.createCourse({title:createTitle.value,grade:newGrade.value,subject:newSubject.value})).id;courseId.value=id;selected.value=null;draft.value=null;tab.value='content';await router.replace({query:{course:id}})}else if(modal.value==='unit'){if(!course.value)throw new Error('请先创建课程。');await api.createUnit({courseId:courseId.value,title:createTitle.value,position:course.value.units.length+1})}else{id=(await api.createLesson({unitId:createUnitId.value||course.value?.units[0]?.id,title:createTitle.value,position:allLessons.value.length+1})).id}const wasLesson=modal.value==='lesson';modal.value='';createTitle.value='';await lists();if(wasLesson)await select(id)})}
async function saveStructure(){await run(async()=>{await api.saveCourse(course.value.id,course.value);for(const u of course.value.units)await api.saveUnit(u.id,u);await lists();notice.value='课程目录已保存'})}
async function reorderLesson(lesson,unit,index,delta){const target=index+delta;if(target<0||target>=unit.lessons.length)return;await run(async()=>{const neighbor=unit.lessons[target];await api.saveLesson(lesson.id,{position:neighbor.position});await api.saveLesson(neighbor.id,{position:lesson.position});await lists()})}
async function saveKnowledge(){await run(async()=>{const empty=points.value.findIndex(p=>!p.name?.trim());if(empty>=0)throw new Error('请填写第 '+(empty+1)+' 个知识点的名称。');points.value=await api.saveKnowledge(points.value);notice.value='知识前置关系已保存'})}
async function history(id){await run(async()=>{historyContent.value=await api.lesson(selected.value.id,id);preview.value=true})}
onMounted(async()=>{try{await lists();if(route.query.course){if(!catalog.value.some(c=>c.id===route.query.course))throw new Error('课程不存在。');courseId.value=String(route.query.course)}caseOptions.value=(await modelApi.search('')).items;const id=route.query.lesson||allLessons.value.find(l=>l.courseId===courseId.value)?.id;if(id)await select(String(id))}catch(e){error.value=e.message}finally{loading.value=false}});

watch(()=>route.query.course,id=>{if(id&&id!==courseId.value&&!loading.value)chooseCourse(String(id))});
watch(()=>route.query.lesson,id=>{if(id&&id!==selected.value?.id&&!loading.value)select(String(id))});
</script>
<template>
<PageHeading title="课程内容"><AppButton variant="outline" :disabled="busy" @click="run(lists)"><RefreshCw :size="16"/>刷新目录</AppButton><AppButton @click="modal='course'"><Plus :size="16"/>新建课程</AppButton></PageHeading>
<AppAlert type="error" v-if="error" role="alert" class="form-error">{{ error }}</AppAlert><p v-if="notice" role="status" class="library-notice">{{ notice }}</p><p v-if="loading" role="status">读取中…</p>
<div class="curriculum-workbench">
<aside class="curriculum-tree"><AppSelect :model-value="courseId" @update:model-value="chooseCourse" label="选择课程" :options="catalog.map(c=>({value:c.id,label:c.title}))"/><label for="curriculum-search" class="sr-only">搜索课时</label><Input id="curriculum-search" v-model="search" placeholder="搜索课时" class="curriculum-search"/><div class="curriculum-tree-actions"><AppButton size="sm" variant="ghost" :disabled="!course" @click="modal='unit'"><Plus :size="15"/>单元</AppButton><AppButton size="sm" variant="ghost" :disabled="!course?.units.length" @click="modal='lesson';createUnitId=course.units[0].id"><Plus :size="15"/>课时</AppButton></div><p v-if="!course?.units.length" class="ai-empty">先添加一个单元</p><p v-if="search.trim()&&!filteredUnits.length" class="ai-empty">没有匹配的课时</p><section v-for="unit in filteredUnits" :key="unit.id"><h3 v-if="course.units.length>1||unit.title!==course.title">{{ unit.title }}</h3><div v-for="(lesson,i) in unit.lessons" :key="lesson.id" class="curriculum-tree-row"><button :class="{active:selected?.id===lesson.id}" :disabled="busy" @click="select(lesson.id)"><span>{{ String(i+1).padStart(2,'0') }}</span><strong>{{ lesson.draft?.title||lesson.title }}</strong><small>{{ lesson.status==='published'?'已发布':lesson.status==='withdrawn'?'已停用':'草稿' }}</small></button><div class="curriculum-tree-order"><AppButton variant="ghost" size="icon-sm" :aria-label="lesson.title+'上移'" :disabled="busy||i===0" @click="reorderLesson(lesson,unit,i,-1)"><ArrowUp :size="12"/></AppButton><AppButton variant="ghost" size="icon-sm" :aria-label="lesson.title+'下移'" :disabled="busy||i===unit.lessons.length-1" @click="reorderLesson(lesson,unit,i,1)"><ArrowDown :size="12"/></AppButton></div></div></section><AppButton variant="ghost" @click="tab='structure'">编辑课程目录</AppButton><AppButton variant="ghost" @click="tab='knowledge'">知识前置关系</AppButton></aside>
<main class="curriculum-main">
<template v-if="tab==='structure'&&course"><Surface><h2>课程目录</h2><div class="curriculum-meta"><label>课程名称<Input v-model="course.title"/></label><label>年级<Input v-model="course.grade"/></label><label>学科<Input v-model="course.metadata.subject"/></label><label>课程顺序<Input type="number" v-model.number="course.metadata.position"/></label></div><div v-for="unit in course.units" :key="unit.id" class="curriculum-unit-edit"><label>单元名称<Input v-model="unit.title"/></label><label>顺序<Input type="number" v-model.number="unit.position"/></label></div><AppButton :disabled="busy" @click="saveStructure">保存目录</AppButton></Surface></template>
<template v-else-if="tab==='knowledge'"><Surface><div class="library-pane-heading"><h2>知识前置关系</h2><AppButton variant="outline" @click="points.push({id:createId('kp'),name:'',prerequisites:[]})"><Plus :size="16"/>知识点</AppButton></div><div v-for="point in points" :key="point.id" class="curriculum-knowledge-row"><label>知识点名称<Input v-model="point.name"/></label><label>别名（每行一个）<Textarea :model-value="(point.aliases||[]).join('\n')" @update:model-value="point.aliases=$event.split('\n').map(s=>s.trim()).filter(Boolean)"/></label><fieldset><legend>前置知识</legend><AppCheckbox v-for="other in points.filter(p=>p.id!==point.id)" :key="other.id" v-model="point.prerequisites" :value="other.id">{{ other.name||'未命名知识点' }}</AppCheckbox></fieldset></div><AppButton :disabled="busy" @click="saveKnowledge">保存知识关系</AppButton></Surface></template>
<template v-else-if="selected&&draft"><div class="curriculum-editor-heading"><div><h2>{{ draft.title }}</h2><Status :tone="selected.reviewed?'green':'neutral'">{{ selected.draft?(selected.reviewed?'已核对':'草稿'):selected.status==='withdrawn'?'已停用':'已发布 v'+selected.published?.version }}</Status></div><div class="library-actions"><AppButton variant="outline" @click="historyContent=null;preview=true"><Eye :size="16"/>预览</AppButton><template v-if="selected.draft"><AppButton variant="outline" :disabled="busy" @click="run(save)"><Save :size="16"/>{{ busy?'处理中…':'保存草稿' }}</AppButton><AppButton variant="outline" :disabled="busy" @click="action('review')">核对内容</AppButton><AppButton :disabled="busy||!selected.reviewed||dirty" @click="action('publish')"><Upload :size="16"/>发布</AppButton></template><AppButton v-else :disabled="busy" @click="action('revise')">创建修订</AppButton><AppButton v-if="selected.status==='published'" variant="ghost" :disabled="busy" @click="action('withdraw')">停用</AppButton></div></div>
<section v-if="!selected.draft" class="admin-published-outline"><div class="admin-published-facts"><span>{{draft.grade}} 　 {{draft.subject}}</span><span>{{draft.duration}} 分钟</span><span>{{draft.blocks.length}} 节内容 　 {{draft.questions.length}} 题</span></div><ol><li v-for="(block,i) in draft.blocks" :key="block.id"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{block.title}}</strong><span>{{blockNames[block.type]||'内容'}}</span></li></ol><AppButton variant="outline" @click="historyContent=null;preview=true">打开学生预览</AppButton></section><component :is="selected.draft?'div':'details'" class="ops-course-editor"><summary v-if="!selected.draft">内容结构与配置</summary><fieldset class="curriculum-edit-pane" :disabled="busy||!selected.draft"><AppTabs v-model="tab" :items="[{value:'content',label:'课时内容'},{value:'questions',label:'题目'},{value:'links',label:'知识与出处'}]"/>
<template v-if="tab==='content'"><div class="admin-lesson-settings"><span>{{draft.grade}} 　 {{draft.subject}} 　 {{draft.duration}} 分钟</span><AppButton variant="ghost" @click="settingsOpen=true">课时设置</AppButton></div>
<draggable v-model="draft.blocks" item-key="id" handle=".curriculum-grip" :disabled="!selected.draft" @change="changed"><template #item="{element:block,index}"><details class="curriculum-block-editor" :open="index===0"><summary>{{String(index+1).padStart(2,'0')}} 　 {{block.title||'新内容块'}}</summary><div class="ops-content-section"><div class="curriculum-block-toolbar"><button type="button" class="curriculum-grip" :aria-label="'拖动'+block.title" @keydown.up.prevent="move(draft.blocks,index,-1)" @keydown.down.prevent="move(draft.blocks,index,1)"><GripVertical :size="16"/></button><AppSelect :model-value="block.type||'explanation'" label="内容块类型" :options="kinds" @update:model-value="changeKind(block,$event)"/><AppButton variant="ghost" size="icon-sm" aria-label="内容块上移" @click="move(draft.blocks,index,-1)"><ArrowUp :size="15"/></AppButton><AppButton variant="ghost" size="icon-sm" aria-label="内容块下移" @click="move(draft.blocks,index,1)"><ArrowDown :size="15"/></AppButton><AppButton variant="ghost" size="icon-sm" aria-label="删除内容块" @click="remove(draft.blocks,index,'内容块')"><Trash2 :size="15"/></AppButton></div><label>标题<Input v-model="block.title" @update:model-value="changed"/></label><label>正文<Textarea v-model="block.content" @update:model-value="changed"/></label><label v-if="selected.draft" class="curriculum-image-input"><Upload :size="16"/><span>{{ block.imageUrl?'更换插图':'选择插图' }}</span><AppFilePicker class="sr-only" accept="image/png,image/jpeg,image/webp" @change="uploadBlock(block,$event)"/></label><label v-if="block.imageUrl">图片说明<Input v-model="block.imageAlt" @update:model-value="changed"/></label><AppButton v-if="block.imageUrl" variant="ghost" @click="block.imageUrl='';changed()">移除插图</AppButton><details class="ops-disclosure"><summary>教师提示</summary><label>提示内容<Input v-model="block.teacherNote" @update:model-value="changed"/></label></details><AppCheckbox v-model="block.required" @change="changed">完成本课必需</AppCheckbox><div v-if="block.type==='activity'&&block.activity" class="curriculum-meta"><label v-for="(label,key) in {base:'初始数量',step:'每次增加',max:'最多次数'}" :key="key">{{ label }}<Input type="number" v-model.number="block.activity[key]" @update:model-value="changed"/></label></div><fieldset v-if="['practice','check'].includes(block.type)"><legend>关联题目</legend><AppCheckbox v-for="q in draft.questions" :key="q.id" v-model="block.questionIds" :value="q.id" @change="changed">{{ q.prompt||'未填写题目' }}</AppCheckbox></fieldset></div></details></template></draggable><AppButton variant="outline" @click="addBlock"><Plus :size="16"/>添加内容块</AppButton></template>
<template v-else-if="tab==='questions'"><details v-for="(q,i) in draft.questions" :key="q.id" class="curriculum-block-editor" :open="i===0"><summary>{{i+1}}. {{q.prompt||'新题目'}}</summary><label class="field-label">用途<AppSelect v-model="q.kind" :options="questionKinds" label="题目用途" @update:model-value="changed"/></label><QuestionEditor :question="q" :subject="draft.subject" @change="changed"/><KnowledgePicker v-model="q.knowledgeIds" :points="points" @update:model-value="changed"/><AppButton variant="ghost" @click="remove(draft.questions,i,'题目')">删除题目</AppButton></details><AppButton variant="outline" @click="addQuestion"><Plus :size="15"/>添加题目</AppButton></template><template v-else><label class="field-label">内容来源<Textarea v-model="draft.source" @update:model-value="changed"/></label><AppSelect :model-value="draft.caseId||'none'" label="参考案例" :options="[{value:'none',label:'不关联案例'},...caseOptions.map(c=>({value:c.id,label:c.title}))]" @update:model-value="draft.caseId=$event==='none'?null:$event;draft.caseVersionId=null;changed()"/><RouteButton v-if="draft.caseId" :route="'case-detail?caseId='+draft.caseId+(draft.caseVersionId?'&versionId='+draft.caseVersionId:'')" secondary>阅读参考案例与原文</RouteButton><fieldset v-for="(label,key) in {knowledgeIds:'本课知识点',prerequisiteIds:'前置知识'}" :key="key"><legend>{{ label }}</legend><AppCheckbox v-for="p in points" :key="p.id" v-model="draft[key]" :value="p.id" @change="changed">{{ p.name }}</AppCheckbox></fieldset></template></fieldset></component>
<details v-if="selected.versions?.length" class="curriculum-versions"><summary>历史发布版本</summary><AppButton v-for="v in selected.versions" :key="v.id" variant="ghost" @click="history(v.id)">版本 {{ v.number }}</AppButton></details></template>
<AppEmpty v-else class="empty-state"><BookOpen :size="28"/><h3>选择或新建课时</h3></AppEmpty>
</main></div>
<AppDialog :open="!!modal" @update:open="!$event&&(modal='')" :title="modal==='course'?'新建课程':modal==='unit'?'新建单元':'新建课时'"><form @submit.prevent="create" class="curriculum-dialog"><label>名称<Input v-model="createTitle" required/></label><SubjectFields v-if="modal==='course'" v-model:grade="newGrade" v-model:subject="newSubject"/><AppSelect v-if="modal==='lesson'" v-model="createUnitId" label="所属单元" :options="course?.units.map(u=>({value:u.id,label:u.title}))||[]"/><AppAlert type="error" v-if="error" class="form-error">{{ error }}</AppAlert><AppButton type="submit" :disabled="busy">创建</AppButton></form></AppDialog>
<AppDialog v-model:open="settingsOpen" title="课时设置"><form v-if="draft" class="curriculum-dialog" @submit.prevent="settingsOpen=false"><div class="curriculum-meta"><label>课时标题<Input id="curriculum-title" v-model="draft.title" @update:model-value="changed"/></label><label>学习时长（分钟）<Input type="number" v-model.number="draft.duration" @update:model-value="changed"/></label><SubjectFields v-model:grade="draft.grade" v-model:subject="draft.subject" @update:grade="changed" @update:subject="changed"/></div><label class="field-label" for="curriculum-goal">学习目标</label><Textarea id="curriculum-goal" v-model="draft.goal" @update:model-value="changed"/><AppButton type="submit">返回编辑</AppButton></form></AppDialog>
<AppDialog v-model:open="preview" title="学生预览" content-class="library-preview"><LessonPreview :lesson="historyContent||draft"/></AppDialog>
</template>
